-- FA Grocery Market starter schema. Inspect existing objects before running on an existing project.
create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null default 'Other groceries',price numeric(12,2) not null check(price>=0),unit text not null default 'each',description text not null default '',image_url text,active boolean not null default true,stock_quantity integer not null default 0 check(stock_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_name text not null,phone text not null,address text not null,notes text not null default '',total numeric(12,2) not null check(total>=0),payment_method text not null check(payment_method in('mobile_money','cash_on_delivery')),status text not null default 'pending' check(status in('pending','confirmed','preparing','out_for_delivery','completed','cancelled')),created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),line_total numeric(12,2) not null check(line_total>=0));
create or replace function public.is_fa_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admin_users au where au.user_id=(select auth.uid())); $$;
revoke all on function public.is_fa_admin() from public;grant execute on function public.is_fa_admin() to authenticated;
alter table public.admin_users enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
drop policy if exists fa_admin_users_read_self on public.admin_users;drop policy if exists fa_products_public_read_active on public.products;drop policy if exists fa_products_admin_all on public.products;drop policy if exists fa_orders_admin_read on public.orders;drop policy if exists fa_orders_admin_update on public.orders;drop policy if exists fa_order_items_admin_all on public.order_items;
create policy fa_admin_users_read_self on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
create policy fa_products_public_read_active on public.products for select to anon,authenticated using(active=true or (select public.is_fa_admin()));
create policy fa_products_admin_all on public.products for all to authenticated using((select public.is_fa_admin())) with check((select public.is_fa_admin()));
create policy fa_orders_admin_read on public.orders for select to authenticated using((select public.is_fa_admin()));
create policy fa_orders_admin_update on public.orders for update to authenticated using((select public.is_fa_admin())) with check((select public.is_fa_admin()));
create policy fa_order_items_admin_all on public.order_items for all to authenticated using((select public.is_fa_admin())) with check((select public.is_fa_admin()));
grant select on public.products to anon,authenticated;grant insert,update,delete on public.products to authenticated;grant select on public.admin_users to authenticated;grant select,update on public.orders to authenticated;grant select,insert,update,delete on public.order_items to authenticated;revoke all on public.orders from anon,authenticated;grant select,update on public.orders to authenticated;
-- Checkout is intentionally not open to anonymous inserts. A server-side Edge Function must validate current prices and stock, then create orders/order_items.
drop policy if exists fa_product_images_public_read on storage.objects;drop policy if exists fa_product_images_admin_insert on storage.objects;drop policy if exists fa_product_images_admin_update on storage.objects;drop policy if exists fa_product_images_admin_delete on storage.objects;
create policy fa_product_images_public_read on storage.objects for select to anon,authenticated using(bucket_id='fa-product-images');
create policy fa_product_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='fa-product-images' and (select public.is_fa_admin()));
create policy fa_product_images_admin_update on storage.objects for update to authenticated using(bucket_id='fa-product-images' and (select public.is_fa_admin())) with check(bucket_id='fa-product-images' and (select public.is_fa_admin()));
create policy fa_product_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='fa-product-images' and (select public.is_fa_admin()));
